INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7444, NULL, NULL, 2486, 'Night Trap', 'Night Trap', 'game', 1992, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p5f.jpg', NULL, 'Five girls go to a party to a nice house on a lakeside. Five girls disappear without a trace... Now another five girls go there, in order to spend the vacation with the Martins, the owners of the house, in particular with the lovely Ms. Martin. This time, you should not let them die a gruesome death! Because "nice people" can sometimes turn out to be... yes, that''s right - vampires. The whole house is full of traps, that are intended to catch the poor innocent girls, so that the vampires can suck their blood... ugh. Luckily, the brave adventurer is there in order to cease to be hunted and to become a hunter instead! Set the traps so that they will capture the villains themselves, using precise timing and good organization.', 'https://www.igdb.com/games/night-trap', '["3DO Interactive Multiplayer", "Mac", "DOS", "Sega CD"]', NULL, NULL, 0, 1.12, '2026-08-05 03:13:48', '2026-08-05 03:13:48');
