INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7480, NULL, NULL, 223, 'The Sims', 'The Sims', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8j9a.jpg', NULL, 'The Sims is a life-building simulation with emphasis on intimate details of individual characters rather than expansion of an entire society or civilization. You are in control of nearly every aspect of the lives of the individuals who make up your chosen population in the neighborhood. Characters are developed from the ground up and you infuse and mold them with personalities, looks, desires, moods, urges, living arrangements, career and personal choices, life styles, and reactions.', 'https://www.igdb.com/games/the-sims', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 2.145, '2026-08-05 03:13:48', '2026-08-05 03:13:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7481, 13428, 'tt0145547', NULL, 'Two Hands', 'Two Hands', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/k5jokQZjJ8hT8FSaStbfgY7dUnC.jpg', 'https://image.tmdb.org/t/p/original/9Jd2YrhSsnRyeJDqRJQK2fqPMMt.jpg', '19-year-old Jimmy is just scraping by in the red-light district of Sydney. When local crime lord Pando offers him a shot at working for his syndicate, Jimmy jumps at the chance to deliver a costly package. But, when Jimmy gets jacked by a couple of kids, he''s indebted to the dangerous gangster for $10,000. Running out of time, he schemes to rob a bank to save himself and a beautiful girl he desires from a gruesome demise.', NULL, NULL, 2.3728, 6.571, 0, 1.01, '2026-08-05 03:13:48', '2026-08-05 03:13:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7482, 24748, 'tt0057163', NULL, 'Hud', 'Hud', 'movie', 1963, 'https://image.tmdb.org/t/p/w500/A168bF52vmAIGkC2Qafj7M2EmaE.jpg', 'https://image.tmdb.org/t/p/original/dlmROevxOVYtZXRUzt6DGJzl9BL.jpg', 'Hud Bannon is a ruthless young man who tarnishes everything and everyone he touches. Hud represents the perfect embodiment of alienated youth, out for kicks with no regard for the consequences. There is bitter conflict between the callous Hud and his stern and highly principled father, Homer. Hud''s nephew Lon admires Hud''s cheating ways, though he soon becomes too aware of Hud''s reckless amorality to bear him anymore. In the world of the takers and the taken, Hud is a winner. He''s a cheat, but, he explains, "I always say the law was meant to be interpreted in a lenient manner."', NULL, NULL, 3.9457, 7.3, 0, 1.01, '2026-08-05 03:13:48', '2026-08-05 03:13:48');
