INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7532, 336, 'tt0067140', NULL, 'Duck, You Sucker', 'Giù la testa', 'movie', 1971, 'https://image.tmdb.org/t/p/w500/nWmAtZf83qpOai0fzehf7Hn1S3R.jpg', 'https://image.tmdb.org/t/p/original/tXjtTg1TcpqUePNgdFrBg56hMUC.jpg', 'At the beginning of the 1913 Mexican Revolution, greedy bandit Juan Miranda and idealist John H. Mallory, an Irish Republican Army explosives expert on the lam from the British, fall in with a band of revolutionaries plotting to strike a national bank. When it turns out that the government has been using the bank as a hiding place for illegally detained political prisoners -- who are freed by the blast -- Miranda becomes a revolutionary hero against his will.', NULL, NULL, 7.1999, 7.669, 0, 1.01, '2026-08-05 03:13:48', '2026-08-05 03:13:48');
