INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7542, 46645, 'tt0945383', NULL, 'Querô', 'Querô', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/gZXhCMSoapkSGqnYRhKcpxQfYA7.jpg', 'https://image.tmdb.org/t/p/original/wHhluS1ZZ2ohZR5DIWGhDjTVbEQ.jpg', 'Querô is an orphan teenager, living alone near the docks in Santos, Brazil. His mother, a prostitute, died when he was a baby, and he was raised in the bordello where she worked. Believing he rules his own destiny, he refuses to compromise with anyone else, the corrupt policemen always chasing him, the oppressive discipline in the juvenile institution Febem, or the drug dealers who try to lure him. But this independence has a price.', NULL, NULL, 1.1418, 6.212, 0, 11.02, '2026-08-05 03:13:48', '2026-08-05 03:13:48');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7543, 177579, 'tt0100508', NULL, 'Rodrigo D. No Future', 'Rodrigo D. No futuro', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/AqsLzU6AQUIHuDsQnqHT1qy0HVV.jpg', 'https://image.tmdb.org/t/p/original/gxUbVZvBqQEtzEjL0xMSViQhP4C.jpg', 'Rodrigo and his friends, restless teenagers from the marginalized neighborhoods on the hillsides of Medellín, spend their time causing trouble. But Rodrigo dreams of playing rock music and brings his friends together to form a punk band that becomes a lifeline amid a web of disorientation, violence, drugs, and fear.', NULL, NULL, 0.4988, 7.0, 0, 11.01, '2026-08-05 03:13:48', '2026-08-05 03:13:48');
