INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (7545, NULL, NULL, 960, 'Max Payne 3', 'Max Payne 3', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mjo.jpg', NULL, 'Max Payne 3 is a third-person shooter in which the player assumes the role of its titular character, Max Payne. A new feature to the series, introduced in Max Payne 3, is the cover system, which allows players to gain a tactical advantage, and avoid taking damage from enemies. To progress through the linear story, players take on enemies throughout levels. The game features interactive cutscenes which transition seamlessly into continuing gameplay; there are no loading screens across gameplay and cutscenes.', 'https://www.igdb.com/games/max-payne-3', '["PlayStation 3", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, NULL, 0, 11.01, '2026-08-05 03:13:48', '2026-08-05 03:13:48');
