UPDATE "recommendations" SET "tmdb_id"=25237, "imdb_id"='tt0091251', "igdb_id"=NULL, "title"='Come and See', "original_title"='Иди и смотри', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/qNbMsKVzigERgJUbwf8pKyZogpb.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3Na31ta8vDuKOgQuPLdSZLs8bCB.jpg', "overview"='The invasion of a village in Belarus by German forces sends young Florya into the forest to join the weary Resistance fighters, against his family''s wishes. There he meets a girl, Glasha, who accompanies him back to his village. On returning home, Florya finds his family and fellow peasants massacred. His continued survival amidst the brutal debris of war becomes increasingly nightmarish, a battle between despair and hope.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.6455, "vote_average"=8.204, "is_ambiguous"=0, "evidence_score"=9.59285714285714341e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-05 03:13:48' WHERE "id"=1103;
