UPDATE "recommendations" SET "tmdb_id"=14553, "imdb_id"='tt0117737', "igdb_id"=NULL, "title"='Stealing Beauty', "original_title"='Stealing Beauty', "media_type"='movie', "release_year"=1996, "poster_url"='https://image.tmdb.org/t/p/w500/5ugxnyVmBK952bwOcE4M0szNimx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bJFapHYlJIhXpfqH8uaNLtUxHwD.jpg', "overview"='Lucy Harmon, an American teenager is arriving in the lush Tuscan countryside to be sculpted by a family friend who lives in a beautiful villa. Lucy visited there four years earlier and exchanged a kiss with an Italian boy with whom she hopes to become reacquainted.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.4414, "vote_average"=6.676, "is_ambiguous"=0, "evidence_score"=9.28000000000000113e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-05 03:13:48' WHERE "id"=2253;
UPDATE "recommendations" SET "tmdb_id"=286565, "imdb_id"='tt3622592', "igdb_id"=NULL, "title"='Paper Towns', "original_title"='Paper Towns', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/lVW67w7eWwmBhbBCc4f983pO8m6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mwoIzHsliirmS0IlSrf2DvVouid.jpg', "overview"='Quentin Jacobsen has spent a lifetime loving the magnificently adventurous Margo Roth Spiegelman from afar. So when she cracks open a window and climbs back into his life dressed like a ninja and summoning him for an ingenious campaign of revenge, he follows. After their all-nighter ends and a new day breaks, Quentin arrives at school to discover that Margo, always an enigma, has now become a mystery. But Quentin soon learns that there are clues, and they''re for him. Urged down a disconnected path, the closer Quentin gets, the less he sees of the girl he thought he knew.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.2463, "vote_average"=6.155, "is_ambiguous"=0, "evidence_score"=9.09166666666666678e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-05 03:13:48' WHERE "id"=2254;
UPDATE "recommendations" SET "tmdb_id"=14832, "imdb_id"='tt0106535', "igdb_id"=NULL, "title"='The Cement Garden', "original_title"='The Cement Garden', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/dnEoE3tHBStCXZx2i9qsUYkwucu.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/WQdxfSioBfSK6fHZxkE8feciMl.jpg', "overview"='After the death of her husband, the mother of Julie, Jack, Sue and Tom begins to suffer from a mysterious illness. Aware that she is going to have to go into hospital she opens a bank account for the children, so that they can be financially self-sufficient and will be able to avoid being taken into care by the authorities. Unfortunately she also dies and Julie and Jack (the older, teenage children) decide to hide her body in the basement so that they can have free reign of their household. Soon Tom has taken to dressing as a girl whilst Sue has become increasingly reticent, confiding only to her diary, meanwhile Jack and Julie sense an attraction developing for each other. However Julie''s new beau, Derek, threatens to unearth the many dark secrets within this family as he becomes increasingly suspicious of Jack.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.1049, "vote_average"=6.759, "is_ambiguous"=0, "evidence_score"=6.76, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-05 03:13:48' WHERE "id"=2256;
