UPDATE "recommendations" SET "tmdb_id"=10166, "imdb_id"='tt0100944', "igdb_id"=NULL, "title"='The Witches', "original_title"='The Witches', "media_type"='movie', "release_year"=1990, "poster_url"='https://image.tmdb.org/t/p/w500/mPYBjVkeHakkPGY7WaKyyNU4RWm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hehaK1jIuTOvRPGPccVivZcZ2Cb.jpg', "overview"='While staying at a hotel in England with his grandmother, Helga, a young boy named Luke inadvertently spies on a convention of witches. The Grand High Witch reveals a plan to turn all children into mice via a magical formula. When they discover the eavesdropper, the witches test the formula on him. Now, with the help of Helga and hotel manager Mr Stringer, Luke the mouse must fight back against the witches.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.8963, "vote_average"=6.94, "is_ambiguous"=0, "evidence_score"=1.08771428571428572e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-05 03:13:48' WHERE "id"=2934;
