UPDATE "recommendations" SET "tmdb_id"=37861, "imdb_id"='tt0862467', "igdb_id"=NULL, "title"='Valhalla Rising', "original_title"='Valhalla Rising', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/7LBMcAx6XHwEduIsBYipvUke9n.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5UTOmyAIe7icGgjc5ETOZNMITmj.jpg', "overview"='Scandinavia, 1,000 AD. For years, One Eye, a mute warrior of supernatural strength, has been held prisoner by the Norse chieftain Barde. Aided by Are, a boy slave, One Eye slays his captor and together he and Are escape, beginning a journey into the heart of darkness. On their flight, One Eye and Are board a Viking vessel, but the ship is soon engulfed by an endless fog that clears only as the crew sights an unknown land. As the new world reveals its secrets and the Vikings confront their terrible and bloody fate, One Eye discovers his true self.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.8751, "vote_average"=6.108, "is_ambiguous"=0, "evidence_score"=1.25933333333333337e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-05 03:13:48' WHERE "id"=2954;
