UPDATE "recommendations" SET "tmdb_id"=60747, "imdb_id"='tt1234719', "igdb_id"=NULL, "title"='Red Dawn', "original_title"='Red Dawn', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/pwOcFK1hFZ5NJybBGfvzU6UHCPg.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jFh87Hj9Yp8QQPYmcNBAZNaa4Y.jpg', "overview"='A city in Washington state awakens to the surreal sight of foreign paratroopers dropping from the sky—shockingly, the U.S. has been invaded and their hometown is the initial target. Quickly and without warning, the citizens find themselves prisoners and their town under enemy occupation. Determined to fight back, a group of young patriots seek refuge in the surrounding woods, training and reorganizing themselves into a guerrilla group of fighters.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.179, "vote_average"=5.713, "is_ambiguous"=0, "evidence_score"=2.02, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-05 03:13:48' WHERE "id"=3705;
UPDATE "recommendations" SET "tmdb_id"=250574, "imdb_id"='tt2428170', "igdb_id"=NULL, "title"='Creep', "original_title"='Creep', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/qn53D574tT0YRyLgirEFHQwGUXw.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/AvrGwToWkP6fp13lzpxsyzoq9JH.jpg', "overview"='Looking for work, Aaron comes across a cryptic online ad: “$1,000 for the day. Filming service. Discretion is appreciated.” Low on cash and full of naiveté, he decides to go for it. He drives to a cabin in a remote mountain town where he meets Josef, his cinematic subject for the day. Josef is sincere and the project seems heartfelt, so Aaron begins to film. But as the day goes on, it becomes clear that Josef is not who he says, and his intentions are not at all pure.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.3603, "vote_average"=6.4, "is_ambiguous"=0, "evidence_score"=15.14625, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-05 03:13:48' WHERE "id"=3756;
