UPDATE "recommendations" SET "tmdb_id"=17295, "imdb_id"='tt0058946', "igdb_id"=NULL, "title"='The Battle of Algiers', "original_title"='La battaglia di Algeri', "media_type"='movie', "release_year"=1966, "poster_url"='https://image.tmdb.org/t/p/w500/2p3AFtOHFvP6OeVMqlnL1zLKOqL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ze7GsNSv418o7pzqc9fb00LWWDk.jpg', "overview"='Paratrooper commander Colonel Mathieu, a former French Resistance fighter during World War II, is sent to Algeria to reinforce efforts to squelch the uprisings of the Algerian War. There he faces Ali la Pointe, a former petty criminal who, as the leader of the Algerian Front de Liberation Nationale, directs terror strategies against the colonial French government occupation. As each side resorts to ever-increasing brutality, no violent act is too unthinkable.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.4312, "vote_average"=7.9, "is_ambiguous"=0, "evidence_score"=7.018, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-05 03:13:48' WHERE "id"=3968;
