UPDATE "recommendations" SET "tmdb_id"=404, "imdb_id"='tt0166896', "igdb_id"=NULL, "title"='The Straight Story', "original_title"='The Straight Story', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/tT9cMiVDdtlcdZxOoFy3VRmEoKk.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1S81PpyGwS8eVx4W75uSKzMw4B0.jpg', "overview"='Retired farmer and widower Alvin Straight learns one day that his distant brother Lyle has suffered a stroke and may not recover. Alvin is determined to make things right with Lyle while he still can, but his brother lives in Wisconsin, while Alvin is stuck in Iowa with no car and no driver''s license. He then has the idea of making the trip on his old lawnmower, thus beginning a picturesque and at times deeply spiritual odyssey.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.6379, "vote_average"=7.742, "is_ambiguous"=0, "evidence_score"=9.58428571428571451e+00, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-05 03:13:48' WHERE "id"=4022;
UPDATE "recommendations" SET "tmdb_id"=11557, "imdb_id"='tt0090060', "igdb_id"=NULL, "title"='St. Elmo''s Fire', "original_title"='St. Elmo''s Fire', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/g2SL3XHJas7hebZ2hhTrYLpKToD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uhAzDn1U51rANMuxQGxxqLORFZs.jpg', "overview"='Reluctant to let go of college life, a close-knit team of seven friends--irresponsible saxophone player Billy, young Republican Alec, his girlfriend Leslie, struggling journalist Kevin, drama queen Jules, lovesick waiter Kirby, and Wendy, a social worker with a heart of gold--realise the party is over. And as the burdens of maturity close in on the young dreamers, the complexities of adulthood and the daily struggle of growing up put their sacred friendship to the test. But everyone knows life is not a bed of roses. It won''t be easy, but when all is said and done, what will it take for St. Elmo''s clique to find its place in the real world?', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6921, "vote_average"=6.13, "is_ambiguous"=0, "evidence_score"=12.01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-05 03:13:48' WHERE "id"=4028;
