UPDATE "recommendations" SET "tmdb_id"=659959, "imdb_id"='tt10457128', "igdb_id"=NULL, "title"='Summer of 85', "original_title"='Été 85', "media_type"='movie', "release_year"=2020, "poster_url"='https://image.tmdb.org/t/p/w500/etH2pm1eMxEjY2dlltpQGLVspv.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hGc9gAIywD3pR7n6xtgkeBpkoIs.jpg', "overview"='What do you dream of when you''re 16-years-old and in a seaside resort in Normandy in the 1980s? A best friend? A lifelong teen pact? Scooting off on adventures on a boat or a motorbike? Living life at breakneck speed? No. You dream of death. Because you can''t get a bigger kick than dying. And that''s why you save it till the very end. The summer holidays are just beginning, and this story recounts how Alexis grew into himself.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.6015, "vote_average"=7.428, "is_ambiguous"=0, "evidence_score"=3.02666666666666683e+00, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-05 03:13:48' WHERE "id"=4376;
