UPDATE "recommendations" SET "tmdb_id"=11286, "imdb_id"='tt0082136', "igdb_id"=NULL, "title"='The Cannonball Run', "original_title"='The Cannonball Run', "media_type"='movie', "release_year"=1981, "poster_url"='https://image.tmdb.org/t/p/w500/pvn9SbMq9q8wJXt3KAp9kP7pmpb.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6Jw1a3ctW5eQjonmPCwPrOeYVNN.jpg', "overview"='A cross-country road race is based on an actual event, the Cannonball Baker Sea to Shining Sea Memorial Trophy Dash, organized by Brock Yates to protest the 55 mph speed limit then in effect in the U.S. The Cannonball was named for Erwin G. "Cannonball" Baker, who in the roaring 20''s rode his motorcycle across the country. Many of the characters are based on ruses developed by real Cannonball racers over the several years that the event was run.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6913, "vote_average"=6.159, "is_ambiguous"=0, "evidence_score"=3.01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-05 03:13:48' WHERE "id"=5439;
UPDATE "recommendations" SET "tmdb_id"=84175, "imdb_id"='tt2125435', "igdb_id"=NULL, "title"='Beasts of the Southern Wild', "original_title"='Beasts of the Southern Wild', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nQJmWekGYlXhezGUb21xFfEfwhH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7LWLPvyfLSb2oOlgWwAwUqA8uKo.jpg', "overview"='Hushpuppy, an intrepid six-year-old girl, lives with her father, Wink, in ''the Bathtub'', a southern Delta community at the edge of the world. Wink’s tough love prepares her for the unraveling of the universe—for a time when he’s no longer there to protect her. When Wink contracts a mysterious illness, nature flies out of whack—temperatures rise and the ice caps melt, unleashing an army of prehistoric creatures called aurochs. With the waters rising, the aurochs coming, and Wink’s health fading, Hushpuppy goes in search of her lost mother.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.254, "vote_average"=6.84, "is_ambiguous"=0, "evidence_score"=12.02, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-05 03:13:48' WHERE "id"=5468;
UPDATE "recommendations" SET "tmdb_id"=22345, "imdb_id"='tt0118665', "igdb_id"=NULL, "title"='Baby Geniuses', "original_title"='Baby Geniuses', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/7zvPhjHkz5YEMUMPyvANCR96RJA.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ywSzDrauG6R52H2zg0HkrPRgvYE.jpg', "overview"='BabyCo is the world''s leading manufacturer in baby products. However, what the public doesn''t know, is that Drs Kinder and Heep, two of its most brilliant scientists, are tirelessly working in complete secrecy to crack the indecipherable code to ''baby talk'': a highly sophisticated language, and the key to the secrets of the universe. Before long, problems arise when mischievous Sly, the smartest of the toddlers, escapes confinement, bent on uniting all babies to free those trapped in the laboratory. Now, Kinder and Heep must find Sly before it is too late.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.1551, "vote_average"=4.114, "is_ambiguous"=0, "evidence_score"=2.02, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-05 03:13:48' WHERE "id"=5507;
