UPDATE "recommendations" SET "tmdb_id"=14022, "imdb_id"='tt0102943', "igdb_id"=NULL, "title"='Slacker', "original_title"='Slacker', "media_type"='movie', "release_year"=1990, "poster_url"='https://image.tmdb.org/t/p/w500/f7Iov2nd0XX9bp2laQEPYPEhisc.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1gjK6oZSQtvhFBbSgkBvn72dPLF.jpg', "overview"='Austin, Texas, is an Eden for the young and unambitious, from the enthusiastically eccentric to the dangerously apathetic. Here, the nobly lazy can eschew responsibility in favor of nursing their esoteric obsessions. The locals include a backseat philosopher who passionately expounds on his dream theories to a seemingly comatose cabbie, a young woman who tries to hawk Madonna''s Pap test to anyone who will listen and a kindly old anarchist looking for recruits.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5568, "vote_average"=6.737, "is_ambiguous"=0, "evidence_score"=1.01883333333333325e+01, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-05 03:13:48' WHERE "id"=6397;
UPDATE "recommendations" SET "tmdb_id"=951, "imdb_id"='tt0099938', "igdb_id"=NULL, "title"='Kindergarten Cop', "original_title"='Kindergarten Cop', "media_type"='movie', "release_year"=1990, "poster_url"='https://image.tmdb.org/t/p/w500/nKnHWwkXyvhzCYWm3FyRAv3qBrl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qWP5TlH1448Pt9ayyuLZJY0NXWj.jpg', "overview"='Hard-edged cop John Kimble gets more than he bargained for when he goes undercover as a kindergarten teacher to get the goods on a brutal drug lord while at the same time protecting the man''s young son. Pitted against a class of boisterous moppets whose antics try his patience and test his mettle, Kimble may have met his match … in more ways than one.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.207, "vote_average"=6.128, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-05 03:13:48' WHERE "id"=6414;
UPDATE "recommendations" SET "tmdb_id"=249798, "imdb_id"='tt0028983', "igdb_id"=NULL, "title"='Head Over Heels', "original_title"='Head Over Heels', "media_type"='movie', "release_year"=1937, "poster_url"='https://image.tmdb.org/t/p/w500/xnZeyStSwoafuCYOM5MVxFH4OiN.jpg', "backdrop_url"=NULL, "overview"='Legendary British musical-comedy favorite Jessie Matthews chalks up another winner with Head Over Heels in Love. The ever-charming Matthews plays Jeanne, a Parisian entertainer who manages to get herself in hot water with the French version of Actors'' Equity and is forced to take a series of jobs under a series of assumed names. Meanwhile, a romantic triangle involving American film star Norma (Helen Whitney Bourne) and gangsters Pierre (Robert Flemyng) and Marcel (Louis Borrell) spells big trouble for all concerned -- including the plucky Jeanne. Highlighted by six sprightly song numbers, Head Over Heels in Love is our girl Jessie''s vehicle all the way, and never mind the "main" plot. The film was directed by Sonnie Hale, who just so happened to be the star''s husband.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.2497, "vote_average"=9.0, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-05 03:13:48' WHERE "id"=6432;
